// dupl - a tool for finding code clones in Go source files.
//
// Reimplementation based on behavioural observation of the original binary.
package main

import (
	"flag"
	"fmt"
	"go/scanner"
	"go/token"
	"log"
	"os"
	"sort"
	"strings"
)

type options struct {
	threshold int
	html      bool
	plumbing  bool
	vendor    bool
	verbose   bool
	fromStdin bool
}

const usage = `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
`

const examples = `
Examples:
  dupl -t 100
	Search clones in the current directory of size at least
	100 tokens.
  dupl $(find app/ -name '*_test.go')
	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
	The same as above.
`

var (
	opt options
	fset = token.NewFileSet()
)

func main() {
	flag.BoolVar(&opt.fromStdin, "files", false, "read file names from stdin one at each line")
	flag.BoolVar(&opt.html, "html", false, "output the results as HTML, including duplicate code fragments")
	flag.BoolVar(&opt.plumbing, "plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	flag.IntVar(&opt.threshold, "threshold", 15, "minimum token sequence size as a clone (default 15)")
	flag.IntVar(&opt.threshold, "t", 15, "minimum token sequence size as a clone (default 15)")
	flag.BoolVar(&opt.vendor, "vendor", false, "check files in vendor directory")
	flag.BoolVar(&opt.verbose, "verbose", false, "explain what is being done")
	flag.BoolVar(&opt.verbose, "v", false, "explain what is being done")
	flag.Usage = printUsage
	flag.Parse()

	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}
	if opt.fromStdin {
		lines := strings.Split(readStdin(), "\n")
		paths = make([]string, 0, len(lines))
		for _, l := range lines {
			l = strings.TrimSpace(l)
			if l != "" {
				paths = append(paths, l)
			}
		}
	}

	files := collectFiles(paths)
	if opt.verbose {
		log.Println("Building suffix tree")
	}
	clones := findClones(files, opt.threshold)
	if opt.verbose {
		log.Println("Searching for clones")
	}
	printClones(clones)
}

func printUsage() {
	out := os.Stderr
	fmt.Fprint(out, usage)
	flag.PrintDefaults()
	fmt.Fprint(out, examples)
}

func readStdin() string {
	var sb strings.Builder
	buf := make([]byte, 4096)
	for {
		n, err := os.Stdin.Read(buf)
		if n > 0 {
			sb.Write(buf[:n])
		}
		if err != nil {
			break
		}
	}
	return sb.String()
}

func collectFiles(paths []string) []string {
	var out []string
	seen := map[string]bool{}
	for _, p := range paths {
		fi, err := os.Stat(p)
		if err != nil {
			continue
		}
		if !fi.IsDir() {
			if !seen[p] {
				seen[p] = true
				out = append(out, p)
			}
			continue
		}
		walk(p, seen, &out)
	}
	sort.Strings(out)
	return out
}

func walk(dir string, seen map[string]bool, out *[]string) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			if name == "vendor" && !opt.vendor {
				continue
			}
			if strings.HasPrefix(name, ".") {
				continue
			}
			walk(dir+"/"+name, seen, out)
			continue
		}
		if strings.HasSuffix(name, ".go") {
			p := dir + "/" + name
			if !seen[p] {
				seen[p] = true
				*out = append(*out, p)
			}
		}
	}
}
GOEOF
echo written"}

