package main

import (
	"go/scanner"
	"go/token"
)

// tokType is the normalised token type used as the suffix tree alphabet.
type tokType int

const (
	tIdent tokType = iota
	tLiteral
	tOperator
	tKeywordBase = 100
)

// Tok is a single token of the analysed source code.
type Tok struct {
	typ  tokType
	line int
	col  int
	end  int // offset just after the token
	off  int // offset of the first byte of the token
	text string
	src  string
}

func classify(t token.Token) tokType {
	switch t {
	case token.IDENT:
		return tIdent
	case token.INT, token.FLOAT, token.IMAG, token.CHAR, token.STRING:
		return tLiteral
	}
	if t.IsKeyword() {
		return tokKeyword(t)
	}
	return tOperator
}

func tokKeyword(t token.Token) tokType {
	return tKeywordBase + tokType(keywordIndex[t])
}

var keywordIndex = func() map[token.Token]tokType {
	m := map[token.Token]tokType{}
	i := tokType(0)
	for _, k := range []token.Token{
		token.BREAK, token.CASE, token.CHAN, token.CONST, token.CONTINUE, token.DEFAULT,
		token.DEFER, token.ELSE, token.FALLTHROUGH, token.FOR, token.FUNC, token.GO,
		token.GOTO, token.IF, token.IMPORT, token.INTERFACE, token.MAP, token.PACKAGE,
		token.RANGE, token.RETURN, token.SELECT, token.STRUCT, token.SWITCH, token.TYPE, token.VAR,
	} {
		m[k] = i
		i++
	}
	return m
}()

// tokenize returns the token stream of one source file. Comments are skipped
// and the package name is not emitted, matching the original tool.
func tokenize(name string, src []byte) []Tok {
	var toks []Tok
	f := fset.AddFile(name, fset.Base(), len(src))
	var s scanner.Scanner
	s.Init(f, src, func(pos token.Position, msg string) {}, scanner.ScanComments)
	for {
		pos, tok, lit := s.Scan()
		if tok == token.EOF {
			break
		}
		if tok == token.COMMENT {
			continue
		}
		p := fset.Position(pos)
		t := Tok{typ: classify(tok), line: p.Line, col: p.Column}
		t.off = f.Offset(pos)
		t.text = lit
		if tok == token.SEMICOLON && lit == "\n" {
			continue
		}
		if tok == token.PACKAGE {
			toks = append(toks, t)
			// skip the package name
			npos, ntok, nlit := s.Scan()
			if ntok == token.EOF {
				break
			}
			np := fset.Position(npos)
			nl := Tok{typ: tLiteral, line: np.Line, col: np.Column, off: f.Offset(npos), text: nlit, src: string(src)}
			_ = nl
			continue
		}
		t.src = string(src)
		toks = append(toks, t)
	}
	return toks
}
