{"command": "cd /workspace/dupl && cat > find.go <<'GOEOF'
package main

import (
	"log"
	"sort"
)

// Fragment describes one occurrence of a clone inside a single file.
type Fragment struct {
	file      string
	startLine int
	endLine   int
	startTok  int
	endTok    int
}

// Group is a group of identical code fragments.
type Group struct {
	frags []Fragment
}

func (g *Group) dup() Group { return Group{frags: append([]Fragment(nil), g.frags...)} }

func findClones(files []string, threshold int) []Group {
	var types []int
	var tokFile []int
	all := map[string][]Tok{}
	for _, f := range files {
		src, ok := readFile(f)
		if !ok {
			continue
		}
		toks := tokenize(f, src)
		all[f] = toks
		for _, t := range toks {
			types = append(types, int(t.typ))
			tokFile = append(tokFile, len(files))
		}
	}
	if len(types) == 0 {
		return nil
	}
	nodes := maximalRepeats(types, threshold)
	if opt.verbose {
		log.Printf("Found %d candidate clones", len(nodes))
	}
	groups := make([]Group, 0, len(nodes))
	for _, n := range nodes {
		var frags []Fragment
		for _, p := range n.occ {
			toks := all[files[n.fileOf[p]]]
			frag := Fragment{file: files[n.fileOf[p]], startTok: p, endTok: p + n.depth - 1}
			if p < len(toks) {
				frag.startLine = toks[p].line
			}
			if q := p + n.depth - 1; q < len(toks) {
				frag.endLine = toks[q].line
			}
			frags = append(frags, frag)
		}
		if len(frags) < 2 {
			continue
		}
		sortFrags(frags)
		groups = append(groups, Group{frags: frags})
	}
	groups = dedup(groups)
	groups = filterSubclones(groups)
	sort.SliceStable(groups, func(i, j int) bool {
		a, b := groups[i], groups[j]
		if len(a.frags) != len(b.frags) {
			return len(a.frags) > len(b.frags)
		}
		return a.frags[0].startTok < b.frags[0].startTok
	})
	return groups
}

func sortFrags(fs []Fragment) {
	sort.SliceStable(fs, func(i, j int) bool {
		if fs[i].file != fs[j].file {
			return fs[i].file < fs[j].file
		}
		if fs[i].startLine != fs[j].startLine {
			return fs[i].startLine < fs[j].startLine
		}
		return fs[i].startTok < fs[j].startTok
	})
}

func contains(a, b Fragment) bool {
	if a.file != b.file {
		return false
	}
	return a.startTok <= b.startTok && b.endTok <= a.endTok
}

func groupContained(sub, sup Group) bool {
	for _, f := range sub.frags {
		found := false
		for _, g := range sup.frags {
			if contains(g, f) {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

func dedup(groups []Group) []Group {
	seen := map[string]bool{}
	out := make([]Group, 0, len(groups))
	for _, g := range groups {
		key := ""
		for _, f := range g.frags {
			key += f.file + fmtKey(f.startLine) + ":" + fmtKey(f.endLine) + ";"
		}
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, g)
	}
	return out
}

func filterSubclones(groups []Group) []Group {
	out := make([]Group, 0, len(groups))
	for _, g := range groups {
		sub := false
		for _, h := range groups {
			if len(h.frags) == len(g.frags) && sameGroup(h, g) {
				continue
			}
			if groupContained(g, h) {
				sub = true
				break
			}
		}
		if !sub {
			out = append(out, g)
		}
	}
	return out
}

func sameGroup(a, b Group) bool {
	if len(a.frags) != len(b.frags) {
		return false
	}
	for i := range a.frags {
		if a.frags[i] != b.frags[i] {
			return false
		}
	}
	return true
}

func fmtKey(n int) string {
	s := ""
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	for n > 0 {
		s = string(rune('0'+n%10)) + s
		n /= 10
	}
	if neg {
		s = "-" + s
	}
	return s
}

func rune(c int) rune { return rune(c) }
GOEOF
echo ok"}

