package main

// repeatNode is a maximal repeat found in the token stream.
type repeatNode struct {
	depth  int
	occ    []int   // start indices of the occurrences in the token stream
	fileOf []int   // index of the file for each occurrence
}

// maximalRepeats finds all maximal repeats of at least `threshold` tokens in
// the concatenated token stream, using a suffix array with LCP and a stack
// based traversal of the corresponding suffix tree.
func maximalRepeats(types []int, threshold int) []repeatNode {
	n := len(types)
	sa, lcp := buildSA(types)
	if n == 0 {
		return nil
	}
	var out []repeatNode
	fileOf := make([]int, 0, 8)
	// stack based enumeration of internal nodes
	type frame struct {
		depth int
		start int
	}
	var stack []frame
	occ := make([]int, 0, 16)
	for i := 1; i <= n; i++ {
		h := 0
		if i < n {
			h = lcp[i]
		}
		start := i
		for len(stack) > 0 && stack[len(stack)-1].depth > h {
			f := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			occ = append(occ, f.start-1)
			for j := f.start; j < i; j++ {
				occ = append(occ, sa[j])
			}
			if f.depth >= threshold && len(occ) >= 2 {
				out = append(out, repeatNode{depth: f.depth, occ: append([]int(nil), occ...)})
			}
			occ = occ[:0]
			start = f.start
		}
		if len(stack) > 0 && stack[len(stack)-1].depth == h {
			continue
		}
		if h >= threshold {
			stack = append(stack, frame{depth: h, start: start})
		}
	}
	return out
}

func buildSA(types []int) ([]int, []int) {
	n := len(types)
	sa := make([]int, n)
	lcp := make([]int, n)
	if n == 0 {
		return sa, lcp
	}
	for i := range sa {
		sa[i] = i
	}
	// simple O(n^2 log n) suffix sort (adequate for a reference tool)
	type kv struct {
		key []int
		i   int
	}
	kvs := make([]kv, n)
	for i := 0; i < n; i++ {
		kvs[i].key = types[i:]
		kvs[i].i = i
	}
	sortSlice(kvs, func(a, b kv) bool {
		ka, kb := a.key, b.key
		m := len(ka)
		if len(kb) < m {
			m = len(kb)
		}
		for j := 0; j < m; j++ {
			if ka[j] != kb[j] {
				return ka[j] < kb[j]
			}
		}
		return len(ka) < len(kb)
	})
	for i := range sa {
		sa[i] = kvs[i].i
	}
	for i := 1; i < n; i++ {
		lcp[i] = commonPrefix(types[sa[i-1]:], types[sa[i]:])
	}
	return sa, lcp
}

func commonPrefix(a, b []int) int {
	m := len(a)
	if len(b) < m {
		m = len(b)
	}
	i := 0
	for i < m && a[i] == b[i] {
		i++
	}
	return i
}

func sortSlice[T any](s []T, less func(a, b T) bool) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && less(s[j], s[j-1]); j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}
