package main

import (
	"fmt"
	"html"
	"os"
	"strings"
)

func printClones(groups []Group) {
	switch {
	case opt.plumbing:
		printPlumbing(groups)
	case opt.html:
		printHTML(groups)
	default:
		printPlain(groups)
	}
}

func printPlain(groups []Group) {
	for _, g := range groups {
		fmt.Printf("found %d clones:\n", len(g.frags))
		for _, f := range g.frags {
			fmt.Printf("  %s:%d,%d\n", f.file, f.startLine, f.endLine)
		}
	}
	fmt.Printf("\nFound total %d clone groups.\n", len(groups))
}

func printPlumbing(groups []Group) {
	for _, g := range groups {
		n := len(g.frags)
		for i, f := range g.frags {
			nxt := g.frags[(i+1)%n]
			fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n", f.file, f.startLine, f.endLine,
				nxt.file, nxt.startLine, nxt.endLine)
		}
	}
}

const htmlHeader = `<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>
`

func printHTML(groups []Group) {
	out := &strings.Builder{}
	out.WriteString(htmlHeader)
	cache := map[string][]string{}
	for _, g := range groups {
		fmt.Fprintf(out, "<h1>#%d found %d clones</h1>\n", 0, len(g.frags))
		for _, f := range g.frags {
			lines, ok := cache[f.file]
			if !ok {
				src, err := os.ReadFile(f.file)
				if err != nil {
					lines = nil
				} else {
					lines = strings.Split(strings.ReplaceAll(string(src), "\r\n", "\n"), "\n")
				}
				cache[f.file] = lines
			}
			fmt.Fprintf(out, "<h2>%s:%d</h2>\n", f.file, f.startLine)
			text := ""
			if lines != nil && f.startLine >= 1 && f.endLine <= len(lines) && f.startLine <= f.endLine {
				text = strings.Join(lines[f.startLine-1:f.endLine], "\n")
			}
			out.WriteString("<pre>" + html.EscapeString(text) + "</pre>\n")
		}
	}
	fmt.Fprint(os.Stdout, out.String())
}
